mapper.select:
SELECT m.message_id AS messageId, m.text_id AS textId, t.message_type AS type, t.message_title AS title, t.message_content AS content, m.send_id AS sendId, m.is_read AS isRead, m.create_time AS createTime FROM tb_message m INNER JOIN tb_message_text t ON m.text_id = t.text_id WHERE m.rec_id = #{userId}
AND t.message_type = #{query.type}
AND (t.message_title LIKE CONCAT('%', #{query.keyword}, '%') OR t.message_content LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY m.create_time DESC, m.message_id DESC
